6: /**
7:  * Hosts a Hairline figure (public/hairline/<name>.js) on the page.
8:  *
9:  * The kernel (public/hairline/kernel.js) is the unchanged engine; each figure
10:  * registers itself through `window.hairline`, exactly as the bench does, and
11:  * is mounted here into a plain div. The page chooses the ink through the
12:  * `.hl-figure` class in globals.css; the figure sets no colour of its own.
13:  */
14: 
15: type Handle = { set: (v: number) => void; destroy: () => void };
16: type Figure = {
17:   name: string;
18:   means: string;
19:   range: [number, number, number];
20:   mount: (
21:     ctx: { stage: HTMLElement; svg: SVGSVGElement; read: { textContent: string | null } },
22:     value: number
23:   ) => Handle;
24: };
25: type HairlineWindow = Window & {
26:   HL?: { inject: (root: Document) => void; mk: (tag: string, attrs: Record<string, string>, parent: Element) => SVGSVGElement };
27:   hairline?: (figure: Figure) => void;
28:   __hairlineFigures?: Record<string, Figure>;
29: };
30: 
31: const BASE = '/hairline';
32: const pending = new Map<string, Promise<void>>();
33: 
34: function load(src: string, type?: string): Promise<void> {
35:   let p = pending.get(src);
36:   if (!p) {
37:     p = new Promise<void>((resolve, reject) => {
38:       const s = document.createElement('script');
39:       s.src = src;
40:       if (type) s.type = type;
41:       s.onload = () => resolve();
42:       s.onerror = () => reject(new Error(`Could not load ${src}`));
43:       document.head.appendChild(s);
44:     });
45:     pending.set(src, p);
46:   }
47:   return p;
48: }
49: 
50: async function figureFor(name: string): Promise<Figure> {
51:   const w = window as HairlineWindow;
52:   w.__hairlineFigures ??= {};
53:   w.hairline ??= (figure) => {
54:     w.__hairlineFigures![figure.name] = figure;
55:   };
56:   await load(`${BASE}/kernel.js`);
57:   if (!w.__hairlineFigures[name]) await load(`${BASE}/${name}.js`, 'module');
58:   const figure = w.__hairlineFigures[name];
59:   if (!figure) throw new Error(`Figure ${name} did not register`);
60:   return figure;
61: }
62: 
63: export interface HairlineFigureProps {
64:   /** File name in public/hairline, without .js */
65:   name: 'pebbles' | 'nest';
66:   /** The slider value as a share of the figure's range: 0, 0.5 (default) or 1 */
67:   intensity?: 0 | 0.5 | 1;
68:   /** What the figure shows, for assistive technology */
69:   label: string;
70:   /** Show the corner read-out that names the part under the pointer */
71:   readout?: boolean;
72:   className?: string;
73: }
74: 
75: export function HairlineFigure({ name, intensity = 0.5, label, readout = true, className }: HairlineFigureProps) {
76:   const stageRef = React.useRef<HTMLDivElement>(null);
77:   const readRef = React.useRef<HTMLSpanElement>(null);
78: 
79:   React.useEffect(() => {
80:     const stage = stageRef.current;
81:     if (!stage) return;
82:     let handle: Handle | null = null;
83:     let cancelled = false;
84: 
85:     figureFor(name)
86:       .then((figure) => {
87:         const w = window as HairlineWindow;
88:         if (cancelled || !w.HL) return;
89:         w.HL.inject(document);
90:         const svg = w.HL.mk('svg', { viewBox: '0 0 400 320', 'aria-hidden': 'true' }, stage);
91:         const read = {
92:           get textContent() {
93:             return readRef.current?.textContent ?? null;
94:           },
95:           set textContent(v: string | null) {
96:             if (readRef.current) readRef.current.textContent = v ?? '';
97:           },
98:         };
99:         const [lo, mid, hi] = figure.range;
100:         const value = intensity === 0 ? lo : intensity === 1 ? hi : mid;
