1: /**
2:  * Nest: a ring of twigs woven in two courses round an empty hollow. The
3:  * pointer is projected onto the ground and the twigs near its bearing lift
4:  * and part, each on its own spring, so the hollow can be looked into; the
5:  * read-out counts the twig and what the nest holds: nothing. At rest the wall
6:  * is high at the back and low at the front, and one bright dot sits in the
7:  * hollow where the first egg would go. The slider is the reach, in twigs.
8:  *
9:  * The pattern: a continuous field, drawn as an empty state. Springs, a
10:  * falloff by distance round the ring, a hit test on the ground plane.
11:  */
12: const {
13:   Cam, fit, prism, proj, rrect, facing, unproj, spring, stepS, poly,
14:   flatDot, mk, place, pointer, put, register, disposer, solid,
15: } = HL;
16: 
17: const N = 15, COURSE = [16, 20.5, 25], REACHES = [0.45, 0.8, 1], W = 3.2, H = 3.3, RISE = 10, STEP = (2 * Math.PI) / N, BACK = (5 * Math.PI) / 4;
18: 
19: /** The share of full lift at u reaches from the pointer: 1 → .31 at 42% → .09 beyond. */
20: const falloff = (u) =>
21:   u <= 0 ? 1 : u <= 0.417 ? 1 - (u / 0.417) * 0.6875 : u <= 1 ? 0.3125 - ((u - 0.417) / 0.583) * 0.2185 : 0.094;
22: /** A fixed scatter in 0..1, so the nest is irregular and always the same. */
23: const jit = (k) => Math.sin(k * 12.9898 + 4.1) * 0.5 + 0.5;
24: 
25: /** A rounded ring turned by a about (cx, cy). */
26: const turn = (ring, a, cx, cy) => {
27:   const c = Math.cos(a), s = Math.sin(a);
28:   return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
29: };
30: 
31: function mount({ stage, svg, read }, value) {
32:   const bag = disposer();
33:   let R = value, over = null;
34: 
35:   const C = Cam(45, 0.5, 3.7);
36:   fit(C, [[-44, -44, -3], [44, 44, -3], [44, -44, -3], [-44, 44, -3], [0, 0, 24]], 200, 168);
37:   const P = proj(C), front = facing(C);
38:   const g = mk("g", {}, svg);
39: 
40:   // the ground the nest sits on, and the dim edge of its hollow
41:   const base = rrect(-43, -43, 43, 43, 43, 14), baseIn = rrect(-41, -41, 41, 41, 41, 14);
42:   put(solid(g), prism(P, front, base, baseIn, -3, 0));
43:   const hollow = Array.from({ length: 32 }, (_, k) => P(12 * Math.cos((k / 32) * 2 * Math.PI), 12 * Math.sin((k / 32) * 2 * Math.PI), 0));
44:   mk("path", { d: poly(hollow), class: "nf lo" }, g);
45:   const egg = flatDot(g, C, 1.2, "dot");
46:   place(egg, P(0, 0, 0));
47: 
48:   // three courses of crossed twigs, each wider than the one below, so the wall flares like a bowl;
49:   // then a few stray twigs on the ground, pointing outwards
50:   const twigs = [];
51:   const add = (c, i, th, rr, L, a, z0, live) => {
52:     const k = c * N + i, cx = rr * Math.cos(th), cy = rr * Math.sin(th);
53:     const ring = turn(rrect(-L / 2, -W / 2, L / 2, W / 2, 1.5, 3), a, cx, cy), inner = turn(rrect(-L / 2 + 0.7, -W / 2 + 0.7, L / 2 - 0.7, W / 2 - 0.7, 0.8, 3), a, cx, cy);
54:     const r0 = live ? 2.8 * (1 + Math.cos(th - BACK)) * (0.7 + 0.3 * jit(k + 3)) : 0;
55:     twigs.push({ c, live, th, ring, inner, z0, r0, key: cx + cy + c * 0.01, sp: spring(r0, { eps: 0.04 }), drawn: NaN });
56:   };
57:   for (let c = 0; c < 3; c++) for (let i = 0; i < N; i++) {
58:     const k = c * N + i, th = (i + 0.5 * c) * STEP + (jit(k) - 0.5) * 0.2, rr = COURSE[c] + (jit(k + 31) - 0.5) * 3;
59:     add(c, i, th, rr, 19 + jit(k + 7) * 10, th + Math.PI / 2 + (jit(k + 19) - 0.5) * 1.5, c * H * 0.8, true);
60:   }
