45: /**
46:  * Flushes any pending buffered track points for a walk directly into Dexie.
47:  */
48: export async function flushWalkBuffer(walkId: string): Promise<void> {
49:   const timer = debounceTimers.get(walkId);
50:   if (timer) {
51:     clearTimeout(timer);
52:     debounceTimers.delete(walkId);
53:   }
54: 
55:   const buffered = pendingPointsBuffer.get(walkId);
56:   if (!buffered || buffered.length === 0) return;
57: 
58:   const current = await db.walks.get(walkId);
59:   if (!current || current.endedAt !== null) {
60:     pendingPointsBuffer.delete(walkId);
61:     return;
62:   }
