    if (photoSource instanceof Blob) {
      url = URL.createObjectURL(photoSource);
      setImageUrl(url);
    } else if (typeof photoSource === 'string') {
      setImageUrl(photoSource);
    }

    return () => {
      if (url) URL.revokeObjectURL(url);
    };
  }, [canonicalEntry.photo, canonicalEntry.thumbnail]);

  const commonName = confirmed?.commonName || 'Unknown organism';
  const scientificName = confirmed?.scientificName || 'Taxon unassigned';
  const kind = confirmed?.kind || 'other';
  const isVerified = canonicalEntry.verified || confirmed?.verified;
  const KindIcon = getKindIcon(kind);

  return (
    <Link
      href={`/entry/${canonicalEntry.id}`}
      className={cn('group block rounded-[1.25rem] outline-none focus-visible:ring-2 focus-visible:ring-ring', className)}
    >
      <div className="relative aspect-[4/5] w-full overflow-hidden rounded-[1.25rem] border border-border bg-muted/50">
        {imageUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={imageUrl}
            alt={commonName}
            className="h-full w-full object-cover transition-transform duration-700 ease-[cubic-bezier(0.32,0.72,0,1)] group-hover:scale-105"
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center text-muted-foreground">
            <KindIcon className="h-9 w-9 opacity-40" strokeWidth={1.25} />
          </div>
        )}
        <span className="absolute left-2.5 top-2.5 flex items-center gap-1 rounded-full bg-background/85 px-2 py-1 font-mono text-[10px] uppercase tracking-wider backdrop-blur-sm">
          <KindIcon className="h-3 w-3 text-primary" strokeWidth={1.75} />
          {kind}
        </span>
        {encounters > 1 && (
          <span className="absolute bottom-2.5 right-2.5 rounded-full bg-primary px-2 py-1 font-mono text-[10px] text-primary-foreground">
            &times;{encounters}
          </span>
        )}
      </div>

      <div className="px-1 pt-3">
        <div className="flex items-start justify-between gap-2">
          <h3 className="line-clamp-2 font-serif text-lg leading-snug tracking-tight transition-colors group-hover:text-primary">
            {commonName}
          </h3>
          {isVerified && (
            <Check className="mt-1 h-3.5 w-3.5 shrink-0 text-primary" strokeWidth={2.5} aria-label="Verified" />
          )}
        </div>
        <p className="truncate text-xs italic text-muted-foreground">{scientificName}</p>
        <p className="mt-1.5 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">
          {new Date(species.dates[0]).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
        </p>
      </div>
    </Link>
  );
}

