const durationSeconds = walk.endedAt
  ? Math.round((walk.endedAt - walk.startedAt) / 1000)
  : 0;
const confirmedEntries = entries.filter((e) => (e.status === 'confirmed' || e.status === 'identified') && e.confirmed);
const voiceNotes = notes.filter((n) => n.kind === 'voice');

// Pace in min/km
const distanceKm = (walk.distance || 0) / 1000;
const paceMinutes =
  distanceKm > 0 && durationSeconds > 0
    ? (durationSeconds / 60 / distanceKm).toFixed(1)
    : '0.0';

return (
  <div className="paper-grain min-h-dvh bg-background text-foreground flex flex-col pb-28 sm:pb-16">
    {/* Sticky Header */}
    <header className="mx-auto w-full max-w-4xl px-5 pt-10 sm:px-8 sm:pt-24">
      <div className="flex h-12 items-center justify-between gap-3">
        <div className="flex items-center gap-2 min-w-0">
          <Link
            href="/journal"
            className="p-2 -ml-2 text-muted-foreground hover:text-foreground rounded-lg transition-colors shrink-0"
            aria-label="Back to journal"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>

          {isEditingTitle ? (
            <div className="flex items-center gap-1.5 min-w-0">
              <input
                type="text"
                value={titleInput}
                onChange={(e) => setTitleInput(e.target.value)}
                className="h-8 px-2 rounded-md border border-primary bg-background text-sm font-sans font-bold text-foreground focus:outline-none"
                autoFocus
              />
              <button
                type="button"
                onClick={handleSaveTitle}
                className="p-1 rounded-md bg-primary text-primary-foreground hover:bg-primary/90"
                aria-label="Save title"
              >
                <Check className="w-4 h-4" />
              </button>
              <button
                type="button"
                onClick={() => setIsEditingTitle(false)}
                className="p-1 rounded-md text-muted-foreground hover:text-foreground"
                aria-label="Cancel editing"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2 min-w-0">
              <h1 className="font-serif text-2xl font-normal tracking-tight text-foreground truncate">
                {walk.title ||
                  `Walk at ${new Date(walk.startedAt).toLocaleTimeString([], {
                    hour: '2-digit',
                    minute: '2-digit',
                  })}`}
              </h1>
              <button
                type="button"
                onClick={() => setIsEditingTitle(true)}
                className="text-muted-foreground hover:text-primary p-1 rounded transition-colors shrink-0"
                aria-label="Edit walk title"
              >
                <Edit2 className="w-3.5 h-3.5" />
              </button>
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setDeleteDialogOpen(true)}
            className="text-destructive hover:text-destructive hover:bg-destructive/10 h-9 px-2.5 gap-1.5"
          >
            <Trash2 className="w-4 h-4" />
            <span className="text-xs font-semibold hidden sm:inline">Delete Walk</span>
          </Button>
        </div>
      </div>
    </header>

    {/* Main Container */}
    <main className="max-w-4xl w-full mx-auto px-5 sm:px-8 pt-3 flex-1 flex flex-col space-y-4">
      {/* MapLibre Route Replay Map Container */}
      <div className="relative w-full h-72 sm:h-96 rounded-2xl overflow-hidden border border-border shadow-sm">
        <WalkMap
          ref={mapRef}
          userPosition={null}
          trackPoints={walk.trackPoints || []}
          specimenEntries={confirmedEntries}
          audioNotes={notes}
          suggestedRouteLine={walk.routeLine || null}
          isWalkActive={false}
        />
      </div>

      {/* Tab Navigation Controls */}
      <div className="flex items-center border-b border-border gap-2">
        <button
          type="button"
          onClick={() => setActiveTab('stats')}
          className={`pb-2.5 px-3 text-sm font-semibold transition-colors border-b-2 -mb-px ${
            activeTab === 'stats'
              ? 'border-primary text-primary'
              : 'border-transparent text-muted-foreground hover:text-foreground'
          }`}
        >
          Stats & Telemetry
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('specimens')}
          className={`pb-2.5 px-3 text-sm font-semibold transition-colors border-b-2 -mb-px flex items-center gap-1.5 ${
            activeTab === 'specimens'
              ? 'border-primary text-primary'
              : 'border-transparent text-muted-foreground hover:text-foreground'
          }`}
        >
          <span>Confirmed Specimens</span>
          <span className="text-xs px-1.5 py-0.5 rounded-full bg-muted font-mono">
            {confirmedEntries.length}
          </span>
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('notes')}
          className={`pb-2.5 px-3 text-sm font-semibold transition-colors border-b-2 -mb-px flex items-center gap-1.5 ${
            activeTab === 'notes'
              ? 'border-primary text-primary'
              : 'border-transparent text-muted-foreground hover:text-foreground'
          }`}
        >
          <span>Voice Notes</span>
          <span className="text-xs px-1.5 py-0.5 rounded-full bg-muted font-mono">
            {voiceNotes.length}
          </span>
        </button>
      </div>

      {/* Tab 1: Stats */}
      {activeTab === 'stats' && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-2">
          <Card className="border border-border bg-card">
            <CardContent className="p-4 space-y-1">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Clock className="w-3.5 h-3.5 text-primary" />
                <span>Duration</span>
              </div>
              <div className="font-mono text-lg font-bold text-foreground">
                {formatDuration(durationSeconds)}
              </div>
            </CardContent>
          </Card>

          <Card className="border border-border bg-card">
            <CardContent className="p-4 space-y-1">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Route className="w-3.5 h-3.5 text-emerald-500" />
                <span>Distance</span>
              </div>
              <div className="font-mono text-lg font-bold text-foreground">
                {formatDistance(walk.distance || 0)}
              </div>
            </CardContent>
          </Card>

          <Card className="border border-border bg-card">
            <CardContent className="p-4 space-y-1">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Activity className="w-3.5 h-3.5 text-amber-500" />
                <span>Avg Pace</span>
              </div>
              <div className="font-mono text-lg font-bold text-foreground">
                {paceMinutes} <span className="text-xs font-normal text-muted-foreground">min/km</span>
              </div>
            </CardContent>
          </Card>

          <Card className="border border-border bg-card">
            <CardContent className="p-4 space-y-1">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <MapPin className="w-3.5 h-3.5 text-sky-500" />
                <span>GPS Points</span>
              </div>
              <div className="font-mono text-lg font-bold text-foreground">
                {walk.trackPoints?.length || 0}
              </div>
            </CardContent>
          </Card>

          <div className="col-span-2 sm:col-span-4 p-4 rounded-xl border border-border bg-muted/20 text-xs font-sans text-muted-foreground flex flex-wrap items-center justify-between gap-3">
            <div>
              Started: <span className="font-mono text-foreground">{new Date(walk.startedAt).toLocaleString()}</span>
            </div>
            {walk.endedAt && (
              <div>
                Concluded: <span className="font-mono text-foreground">{new Date(walk.endedAt).toLocaleString()}</span>
              </div>
            )}
            <Badge variant="outline" className="capitalize">
              {walk.mode === 'loop' ? 'Loop Route' : 'Free Walk'}
            </Badge>
          </div>
        </div>
      )}

      {/* Tab 2: Specimens */}
      {activeTab === 'specimens' && (
        <div className="space-y-4 pt-2">
          {confirmedEntries.length === 0 ? (
            <div className="p-8 text-center rounded-2xl border border-dashed border-border bg-card/50 text-muted-foreground font-sans text-sm">
              No confirmed specimens recorded on this walk.
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {confirmedEntries.map((entry) => {
                const commonName = entry.confirmed?.commonName || 'Unknown Specimen';
                const scientificName = entry.confirmed?.scientificName || '';
                const kind = entry.confirmed?.kind || 'plant';

                let photoSrc = '';
                const source = entry.thumbnail || entry.photo;
                if (source instanceof Blob) {
                  photoSrc = URL.createObjectURL(source);
                } else if (typeof source === 'string') {
                  photoSrc = source;
                }

                return (
                  <Card
                    key={entry.id}
                    className="border border-border bg-card overflow-hidden hover:border-primary/40 transition-colors"
                  >
                    <CardContent className="p-3.5 flex items-center gap-3">
                      <div className="w-16 h-16 rounded-xl bg-muted/60 overflow-hidden shrink-0">
                        {photoSrc ? (
                          // eslint-disable-next-line @next/next/no-img-element
                          <img
                            src={photoSrc}
                            alt={commonName}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-lg">
                            🌿
                          </div>
                        )}
                      </div>

                      <div className="min-w-0 flex-1 space-y-1">
                        <div className="flex items-center gap-2">
                          <span className="font-sans font-bold text-sm text-foreground truncate">
                            {commonName}
                          </span>
                          <Badge variant="outline" className="text-[10px] capitalize">
                            {kind}
                          </Badge>
                        </div>
                        <p className="font-sans italic text-xs text-muted-foreground truncate">
                          {scientificName}
                        </p>
                        <Link
                          href={`/entry/${entry.id}`}
                          className="inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline pt-0.5"
                        >
                          <span>Inspect Specimen</span>
                          <ExternalLink className="w-3 h-3" />
                        </Link>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Tab 3: Notes */}
      {activeTab === 'notes' && (
        <div className="space-y-3 pt-2">
          {voiceNotes.length === 0 ? (
            <div className="p-8 text-center rounded-2xl border border-dashed border-border bg-card/50 text-muted-foreground font-sans text-sm">
              No voice notes recorded during this expedition.
            </div>
          ) : (
            voiceNotes.map((note) => {
              const isPlaying = activePlayingNoteId === note.id;
              return (
                <Card key={note.id} className="border border-border bg-card">
                  <CardContent className="p-4 flex items-start gap-3">
                    <Button
                      size="icon"
                      variant="outline"
                      onClick={() => handlePlayNote(note)}
                      className={`h-10 w-10 rounded-full shrink-0 ${
                        isPlaying
                          ? 'bg-primary text-primary-foreground border-primary'
                          : 'text-primary hover:bg-primary/10'
                      }`}
                      aria-label={isPlaying ? 'Pause audio note' : 'Play audio note'}
                    >
                      {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
                    </Button>

                    <div className="min-w-0 flex-1 space-y-1">
                      <div className="flex items-center justify-between text-xs text-muted-foreground">
                        <span className="font-mono">
                          {new Date(note.createdAt).toLocaleTimeString([], {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </span>
                        {note.duration && (
                          <span className="font-mono">
                            {formatDuration(Math.round(note.duration))}
                          </span>
                        )}
                      </div>
                      <p className="font-sans text-sm text-foreground leading-relaxed">
                        {note.transcript || '(No transcript available)'}
                      </p>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      )}

