'use client';

import * as React from 'react';
import Link from 'next/link';
import { Clock, Route, Mic, ArrowRight } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import type { Walk, Entry, Note } from '@/lib/db';
import { formatDistance, formatDuration, calculateHaversineDistance } from '@/lib/geo';
import { getNaturalCover } from '@/components/hairline/natural-covers';

export interface WalkCardProps {
  walk: Walk;
  entries: Entry[];
  notes: Note[];
  className?: string;
}

export function WalkCard({ walk, entries, notes, className }: WalkCardProps) {
  const durationSeconds = walk.endedAt
    ? Math.round((walk.endedAt - walk.startedAt) / 1000)
    : 0;

  const confirmedEntries = entries.filter(
    (e) => (e.status === 'confirmed' || e.status === 'identified') && e.confirmed
  );
  const voiceNotes = notes.filter((n) => n.kind === 'voice');

  const startTimeStr = new Date(walk.startedAt).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  });

  // Calculate distance if missing or 0 but points exist
  const effectiveDistance = React.useMemo(() => {
    let d = walk.distance || 0;
    if (d === 0 && walk.trackPoints && walk.trackPoints.length > 1) {
      for (let i = 1; i < walk.trackPoints.length; i++) {
        d += calculateHaversineDistance(
          walk.trackPoints[i - 1].lat,
          walk.trackPoints[i - 1].lng,
          walk.trackPoints[i].lat,
          walk.trackPoints[i].lng
        );
      }
      d = Math.round(d);
    }
    return d;
  }, [walk.distance, walk.trackPoints]);

  // First image in the walk, if any
  const firstImageEntry = entries.find((e) => e.thumbnail || e.photo);
  const [firstImageUrl, setFirstImageUrl] = React.useState<string | null>(null);

  React.useEffect(() => {
    if (!firstImageEntry) {
      setFirstImageUrl(null);
      return;
    }
    const src = firstImageEntry.thumbnail || firstImageEntry.photo;
    let url: string | null = null;
    if (src instanceof Blob) {
      url = URL.createObjectURL(src);
      setFirstImageUrl(url);
    } else if (typeof src === 'string') {
      setFirstImageUrl(src);
    }
    return () => {
      if (url) URL.revokeObjectURL(url);
    };
  }, [firstImageEntry]);

  // Hairline natural cover fallback (one of 25 preset figures)
  const naturalCover = React.useMemo(() => getNaturalCover(walk.id), [walk.id]);
  const CoverSvg = naturalCover.svg;

  return (
    <Link
      href={`/journal/${walk.id}`}
      className="group block h-full focus:outline-none focus-visible:ring-2 focus-visible:ring-primary rounded-[1.25rem]"
    >
      <Card
        className={cn(
          'flex flex-col h-full overflow-hidden rounded-[1.25rem] border border-border bg-card shadow-none transition-all duration-300 hover:border-primary/50 hover:shadow-md group-hover:-translate-y-1',
          className
        )}
      >
        {/* Cover Section */}
        {firstImageUrl ? (
          // Cover with image: photo inside white borders (polaroid / museum mount style)
          <div className="relative aspect-[4/3] w-full overflow-hidden bg-muted/40 p-3 sm:p-3.5 flex items-center justify-center border-b border-border/50">
            <div className="relative h-full w-full bg-white dark:bg-white text-zinc-900 p-2 sm:p-2.5 rounded-xl shadow-sm border border-black/10 flex flex-col justify-between overflow-hidden">
              <div className="relative flex-1 w-full overflow-hidden rounded-lg bg-zinc-100">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={firstImageUrl}
                  alt={firstImageEntry?.confirmed?.commonName || 'Expedition cover'}
                  className="h-full w-full object-cover transition-transform duration-700 ease-[cubic-bezier(0.32,0.72,0,1)] group-hover:scale-105"
                />
              </div>
              {firstImageEntry?.confirmed?.commonName && (
                <div className="pt-1 px-0.5 flex items-center justify-between text-[10px] font-sans text-zinc-600 truncate">
                  <span className="font-semibold truncate">{firstImageEntry.confirmed.commonName}</span>
                  <span className="font-mono text-[9px] uppercase tracking-wider text-zinc-400 shrink-0">Specimen</span>
                </div>
              )}
            </div>
          </div>
        ) : (
          // Cover with no image: choose from preset collection of 25 Hairline natural elements
          <div className="relative aspect-[4/3] w-full overflow-hidden bg-muted/20 p-4 flex items-center justify-center border-b border-border/50 group-hover:bg-primary/[0.03] transition-colors">
            <CoverSvg className="h-full w-full text-foreground/75 group-hover:text-primary transition-all duration-500 group-hover:scale-105" />
            <span className="absolute bottom-2.5 right-2.5 rounded-full bg-background/85 backdrop-blur-xs px-2 py-0.5 font-mono text-[9px] uppercase tracking-wider text-muted-foreground border border-border/40 shadow-xs">
              {naturalCover.name}
            </span>
          </div>
        )}

        {/* Card Content Information */}
        <div className="p-4 sm:p-5 flex-1 flex flex-col justify-between space-y-3">
          <div>
            <div className="flex items-center justify-between gap-2">
              <h3 className="font-serif text-lg font-medium leading-snug tracking-tight text-foreground transition-colors group-hover:text-primary truncate">
                {walk.title || `Walk at ${startTimeStr}`}
              </h3>
              <Badge variant="outline" className="text-[10px] capitalize shrink-0">
                {walk.mode === 'loop' ? 'Loop' : 'Free Walk'}
              </Badge>
            </div>

            {/* Telemetry Stats Row */}
            <div className="mt-2.5 flex flex-wrap items-center gap-3 text-xs font-mono text-muted-foreground">
              <div className="flex items-center gap-1.5">
                <Clock className="w-3.5 h-3.5 text-primary" />
                <span className="text-foreground font-semibold">
                  {formatDuration(durationSeconds)}
                </span>
              </div>

              <div className="flex items-center gap-1.5">
                <Route className="w-3.5 h-3.5 text-emerald-600" />
                <span className="text-foreground font-semibold">
                  {formatDistance(effectiveDistance)}
                </span>
              </div>

              {voiceNotes.length > 0 && (
                <div className="flex items-center gap-1.5">
                  <Mic className="w-3.5 h-3.5 text-primary" />
                  <span className="text-foreground font-semibold">
                    {voiceNotes.length}
                  </span>
                </div>
              )}
            </div>
          </div>

          {/* Footer: Finds count or status, with Open route arrow */}
          <div className="pt-2 border-t border-border/60 flex items-center justify-between gap-2 text-xs">
            {confirmedEntries.length > 0 ? (
              <span className="font-sans text-muted-foreground truncate">
                {confirmedEntries.length} confirmed find{confirmedEntries.length === 1 ? '' : 's'}
              </span>
            ) : (
              <span className="font-sans text-muted-foreground italic text-[11px]">
                {notes.length > 0
                  ? `${notes.length} note${notes.length === 1 ? '' : 's'} recorded`
                  : 'Trail recorded'}
              </span>
            )}

            <div className="flex items-center gap-1 font-medium text-muted-foreground group-hover:text-primary transition-colors shrink-0">
              <span className="text-xs">Open</span>
              <ArrowRight className="w-3.5 h-3.5 transition-transform group-hover:translate-x-0.5" />
            </div>
          </div>
        </div>
      </Card>
    </Link>
  );
}

