'use client';

import * as React from 'react';
import Link from 'next/link';
import { Card } from '@/components/ui/card';
import { cn } from '@/lib/utils';
import type { Walk, Entry, Note } from '@/lib/db';
import { getNaturalCover } from '@/components/hairline/natural-covers';

export interface WalkCardProps {
  walk: Walk;
  entries: Entry[];
  notes?: Note[];
  className?: string;
}

export function WalkCard({ walk, entries, className }: WalkCardProps) {
  // First image in the walk, if any
  const firstImageEntry = entries.find((e) => e.thumbnail || e.photo);
  const [firstImageUrl, setFirstImageUrl] = React.useState<string | null>(null);

  React.useEffect(() => {
    if (!firstImageEntry) {
      setFirstImageUrl(null);
      return;
    }
    const src = firstImageEntry.thumbnail || firstImageEntry.photo;
    let url: string | null = null;
    if (src instanceof Blob) {
      url = URL.createObjectURL(src);
      setFirstImageUrl(url);
    } else if (typeof src === 'string') {
      setFirstImageUrl(src);
    }
    return () => {
      if (url) URL.revokeObjectURL(url);
    };
  }, [firstImageEntry]);

  // Hairline natural cover fallback (one of 25 preset figures)
  const naturalCover = React.useMemo(() => getNaturalCover(walk.id), [walk.id]);
  const CoverSvg = naturalCover.svg;

  const startTimeStr = new Date(walk.startedAt).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  });

  const label = walk.title || `Walk at ${startTimeStr}`;

  return (
    <Link
      href={`/journal/${walk.id}`}
      title={label}
      aria-label={label}
      className="group block focus:outline-none focus-visible:ring-2 focus-visible:ring-primary rounded-[1.25rem]"
    >
      <Card
        className={cn(
          'overflow-hidden rounded-[1.25rem] border border-border shadow-none transition-all duration-300 hover:border-primary/50 hover:shadow-md group-hover:-translate-y-1',
          firstImageUrl
            ? 'bg-white dark:bg-white p-3 sm:p-3.5 aspect-[3/4]'
            : 'bg-card p-6 aspect-[3/4] flex items-center justify-center',
          className
        )}
      >
        {firstImageUrl ? (
          // Only image inside white borders
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={firstImageUrl}
            alt={label}
            className="h-full w-full object-cover rounded-lg transition-transform duration-700 ease-[cubic-bezier(0.32,0.72,0,1)] group-hover:scale-105"
          />
        ) : (
          // Natural element cover
          <CoverSvg className="h-full w-full text-foreground/75 group-hover:text-primary transition-all duration-500 group-hover:scale-105" />
        )}
      </Card>
    </Link>
  );
}

