  { dist: 120, count: 1, expected: 1 },
  { dist: 499, count: 1, expected: 1 },
  { dist: 500, count: 1, expected: 2 },
  { dist: 1850, count: 1, expected: 2 },
  { dist: 2000, count: 1, expected: 3 },
  { dist: 4500, count: 2, expected: 3 },
  { dist: 5000, count: 1, expected: 4 },
  { dist: 15000, count: 1, expected: 4 },
];
